import { useState, useEffect, useCallback } from 'react';
import { SessionService } from '@/services/session.service';
import { UserService } from '@/services/user.service';
import { Session } from '@/types/session';
import { User } from '@/types/user';
import { ID } from 'appwrite';
import { useAuth } from './useAuth';

export function useSession() {
    const { userId, loading: authLoading } = useAuth();
    const [session, setSession] = useState<Session | null>(null);
    const [user, setUser] = useState<User | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const fetchUser = useCallback(async () => {
        if (!userId) return;
        try {
            const doc = await UserService.get(userId);
            setUser(doc);
        } catch (e) {
            console.error('Failed to fetch user details', e);
        }
    }, [userId]);

    useEffect(() => {
        fetchUser();
    }, [fetchUser]);

    const createSession = async (username: string) => {
        if (!userId) {
            setError("Authentication not ready");
            return;
        }
        setLoading(true);
        setError(null);

        try {
            // Source of Truth Rule #2: Session Control Layer
            // 1. Create Session Document
            const privateId = ID.unique();
            const sessionPayload = {
                userId,
                privateId,
                expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(), // 24 hours
            };
            const newSession = await SessionService.create(sessionPayload);
            setSession(newSession);
            localStorage.setItem('nexconnect_session_id', newSession.$id);
            localStorage.setItem('nexconnect_private_id', privateId); // For validation logic later if needed

            // 2. Update Pseudonym (User Doc)
            try {
                await UserService.update(userId, { username });
                // Update local state immediately
                if (user) setUser({ ...user, username });
                else fetchUser();
            } catch { }

        } catch (err: any) {
            console.error('Create session failed:', err);
            setError(err.message || 'Failed to create session');
        } finally {
            setLoading(false);
        }
    };

    // Restore Session
    useEffect(() => {
        const checkSession = async () => {
            if (authLoading) return;

            const storedSessionId = localStorage.getItem('nexconnect_session_id');
            if (storedSessionId) {
                try {
                    const restoredSession = await SessionService.get(storedSessionId);
                    // Check if valid and active
                    if (restoredSession.isActive && new Date(restoredSession.expiresAt) > new Date()) {
                        setSession(restoredSession);
                    } else {
                        // Expired or inactive, clear it
                        localStorage.removeItem('nexconnect_session_id');
                        localStorage.removeItem('nexconnect_private_id');
                    }
                } catch {
                    // Not found or error
                    localStorage.removeItem('nexconnect_session_id');
                    localStorage.removeItem('nexconnect_private_id');
                }
            }
            setLoading(false);
        };
        checkSession();
    }, [authLoading]);

    const logout = async () => {
        setLoading(true);
        try {
            if (session) {
                // Rule #6: Wipe / Exit
                await SessionService.expire(session.$id);
            }
        } catch (e) {
            console.error(e);
        } finally {
            setSession(null);
            localStorage.removeItem('nexconnect_session_id');
            localStorage.removeItem('nexconnect_private_id');
            setLoading(false);
        }
    };

    return {
        session,
        user, // The User Doc
        loading: loading || authLoading,
        error,
        createSession,
        logout,
        isAuthenticated: !!session && session.isActive, // Enforce session validity
    };
}
